from math import isqrt


def _primes_up_to(limit: int) -> list[int]:
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start : limit + 1 : p] = b"\x00" * (((limit - start) // p) + 1)
    return [p for p in range(2, limit + 1) if sieve[p]]


_PRIMES = _primes_up_to(1000)


def find_largest_400_number(a: int) -> int:
    """Find the largest 400 number not exceeding a.

    A positive integer N is a 400 number if and only if it has exactly
    two distinct prime factors and each factor has an even exponent.
    """
    root = isqrt(a)
    for candidate in range(root, 1, -1):
        remaining = candidate
        distinct = 0
        for prime in _PRIMES:
            if prime * prime > remaining:
                break
            if remaining % prime == 0:
                distinct += 1
                if distinct > 2:
                    break
                while remaining % prime == 0:
                    remaining //= prime
        if distinct <= 2 and remaining > 1:
            distinct += 1
        if distinct == 2:
            return candidate * candidate
    # The input lower bound guarantees a valid result (36 = 2^2 * 3^2).
    return 36

