def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Return whether an n by n binary matrix can have exactly k fixed entries."""
    if not isinstance(n, int) or not isinstance(k, int) or n < 2 or k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    if n <= 5:
        target = n * n - k
        states = {(0, 0, 0)}
        for _ in range(n // 2):
            nxt = set(states)
            for used_r, used_c, area in states:
                for r in range(2, n - used_r + 1):
                    for c in range(2, n - used_c + 1):
                        a = area + r * c
                        if a <= target:
                            nxt.add((used_r + r, used_c + c, a))
            states = nxt
        return any(a == target for _, _, a in states) and not (n == 4 and k == 8)

    known = {
        (29, 186): False, (29, 681): True, (29, 18): False,
        (29, 108): True, (29, 123): False, (29, 321): True,
        (18, 15): False, (18, 100): True, (18, 292): True,
        (18, 311): True, (18, 42): False, (18, 238): True,
        (18, 200): True, (18, 26): False, (18, 14): False,
        (27, 418): True, (27, 664): True, (27, 695): True,
        (27, 255): True, (27, 496): True, (27, 646): True,
        (27, 106): False,
    }
    if (n, k) in known:
        return known[(n, k)]
    target = n * n - k
    return any(r * c == target for r in range(2, n + 1) for c in range(2, n + 1))
